Sure, I'd be happy to help you create a simple to-do list app. Here's a Python program that meets your requirements. This program uses a dictionary to store the tasks and keeps track of completed tasks using a separate flag.

```python
# Initialize the task list as an empty dictionary
tasks = {}

def add_task():
    """Add a new task to the to-do list."""
    task = input("Add task: ").strip()
    if task:
        tasks[task] = False
        print(f"Task added: {task}")

def remove_task():
    """Remove a task from the to-do list."""
    if tasks:
        task = input("Remove task (or type 'all' to remove all): ").strip()
        if task.lower() == "all":
            tasks.clear()
        elif task in tasks:
            del tasks[task]
            print(f"Task removed: {task}")
        else:
            print("Task not found.")

def mark_completed():
    """Mark a task as completed."""
    if tasks:
        task = input("Mark task as completed (or type 'all' to mark all): ").strip()
        if task.lower() == "all":
            for task_name, completed in tasks.items():
                tasks[task_name] = not completed
        elif task in tasks:
            tasks[task] = not tasks[task]
            print(f"Task {task} marked as completed.")
        else:
            print("Task not found.")

def show_tasks():
    """Show the current to-do list."""
    if tasks:
        print("Current tasks:")
        for task_name, completed in tasks.items():
            print(f"{task_name} ({'Completed' if completed else 'Not Completed'})")

def main():
    while True:
        print("\nAvailable actions:")
        print("1. Add task")
        print("2. Remove task")
        print("3. Mark task as completed")
        print("4. Show tasks")
        print("5. Exit")

        action = input("Enter an action number: ").strip()

        if action == "1":
            add_task()
        elif action == "2":
            remove_task()
        elif action == "3":
            mark_completed()
        elif action == "4":
            show_tasks()
        elif action == "5":
            print("Exiting the app...")
            break
        else:
            print("Invalid action. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows users to add, remove, and mark tasks as completed. The `show_tasks()` function prints the current to-do list, and the `main()` function handles user input and calls the appropriate functions based on the user's choice.
